(function(){'use strict';
const $=s=>document.querySelector(s),S=Staff,M=StaffCash,owner=(new URLSearchParams(location.search).get('owner')||'').toLowerCase(),actor=KashierData.userId();let epoch=0,request=0,current=null;
const active=()=>actor&&KashierData.loggedIn()&&KashierData.userId()===actor,node=(tag,value)=>{const e=document.createElement(tag);if(value!==undefined)e.textContent=String(value);return e;};
function clear(){current=null;$('#staff-cash-paper').hidden=true;$('#staff-cash-rows').replaceChildren();$('#staff-cash-summary').replaceChildren();$('#staff-cash-title').textContent='ڕاپۆرتی کاشی من';$('#staff-cash-print').disabled=$('#staff-cash-export').disabled=true;}
function invalidate(){request++;clear();$('#staff-cash-status').textContent='ماوەکە گۆڕاوە؛ ڕاپۆرتەکە نوێ بکەرەوە.';}
function render(v){current=v;$('#staff-cash-title').textContent=v.store_name+' · '+v.member_name;$('#staff-cash-period').textContent=v.from+' — '+v.to+' · کاتی بەغدا';for(const key of ['sale_cash','sale_credit_cash','collection','full_refund','partial_refund','inflow','outflow','net']){const row=node('div');row.append(node('span',M.kinds[key]||{inflow:'کۆی کاشی وەرگیراو',outflow:'کۆی کاشی گەڕێندراو',net:'جیاوازی کاشی مامەڵەکانی من'}[key]),node('strong',S.format(BigInt(v.summary[key]))+' دینار'));$('#staff-cash-summary').append(row);}for(const r of v.rows){const row=node('tr'),prefix=r.kind==='collection'?'D-':r.kind.includes('refund')?'R-':'K-';row.append(node('td',new Intl.DateTimeFormat('ckb-IQ-u-ca-gregory-nu-latn',{timeZone:'Asia/Baghdad',dateStyle:'short',timeStyle:'medium'}).format(new Date(r.created_at))),node('td',M.kinds[r.kind]),node('td',prefix+r.number),node('td',r.actor_name),node('td',S.format(BigInt(r.delta))+' دینار'));$('#staff-cash-rows').append(row);}$('#staff-cash-paper').hidden=false;$('#staff-cash-empty').hidden=v.rows.length!==0;$('#staff-cash-print').disabled=$('#staff-cash-export').disabled=false;}
async function read(action){if(!active()){clear();location.replace('auth.html?next='+encodeURIComponent('staff-cash.html?owner='+owner));return;}const mine=++request,life=epoch,from=$('#staff-cash-from').value,to=$('#staff-cash-to').value;clear();try{M.range(from,to);$('#staff-cash-status').textContent='پشکنینی مامەڵەکانی خودت…';const v=await KashierData.getCashierCashActivity(owner,from,to);if(mine!==request||life!==epoch||!active())return;M.report(v,owner,actor,from,to);render(v);$('#staff-cash-status').textContent=S.format(v.rows.length)+' مامەڵە · تەنها مامەڵەکانی خودت';if(action==='print')window.print();if(action==='export'){const url=URL.createObjectURL(new Blob([M.csv(v)],{type:'text/csv;charset=utf-8'})),a=node('a');a.href=url;a.download='cashier-cash-'+from+'-'+to+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(e){if(mine===request&&life===epoch){clear();$('#staff-cash-status').textContent=(globalThis.KashierLocale?.message(e.message)??e.message);}}}
$('#staff-cash-form').addEventListener('submit',e=>{e.preventDefault();read();});for(const key of ['from','to'])$('#staff-cash-'+key).addEventListener('input',invalidate);$('#staff-cash-print').addEventListener('click',()=>{if(current)read('print');});$('#staff-cash-export').addEventListener('click',()=>{if(current)read('export');});window.addEventListener('pagehide',()=>{epoch++;invalidate();});window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});window.addEventListener('beforeprint',()=>{if(!active())clear();});const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Baghdad',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),today=['year','month','day'].map(k=>parts.find(p=>p.type===k).value).join('-');$('#staff-cash-from').value=$('#staff-cash-to').value=today;clear();if(!S.uuid(owner))$('#staff-cash-status').textContent='ناسنامەی دوکان نادروستە.';else read();
})();
